import React from 'react';
import '../styles/AlertsCard.css';

const AlertsCard = React.memo(function AlertsCard({ alerts }) {
  const safeAlerts = alerts || [];
  const displayAlerts = safeAlerts.slice(0, 5);

  const getSeverityClass = (severity) => {
    const s = (severity || '').toLowerCase();
    if (s === 'emergency' || s === 'critical') return 'emergency';
    if (s === 'warning') return 'warning';
    return 'normal';
  };

  const formatAlertMessage = (text) => {
    if (typeof text !== 'string') return text;
    const parts = text.split(',');
    if (parts.length > 1 && parts.every(p => p.includes(':'))) {
      return (
        <span className="alert-msg-formatted">
          {parts.map((p, i) => (
            <span key={i} className="alert-msg-part">
              {p.trim()}{i < parts.length - 1 ? <span className="alert-msg-comma">, </span> : ''}
            </span>
          ))}
        </span>
      );
    }
    return text;
  };

  return (
    <div className="alerts-card">
      {/* ── Header ────────────────────────────────── */}
      <div className="ac-header">
        <span className="ac-title">Recent Alerts</span>
        <span className="ac-count">
          {safeAlerts.length} alert{safeAlerts.length !== 1 ? 's' : ''}
        </span>
      </div>

      {/* ── Alert list ────────────────────────────── */}
      {displayAlerts.length > 0 ? (
        <div className="ac-list">
          {displayAlerts.map((alert, idx) => {
            const sevClass = getSeverityClass(alert.severity);
            return (
              <div key={alert.id || idx} className="ac-item">
                <span className={`ac-severity-pip ${sevClass}`} />
                <span className={`ac-severity-label ${sevClass}`}>
                  {alert.severity || 'INFO'}
                </span>
                <span className="ac-message">
                  {formatAlertMessage(alert.alert_type || alert.message || 'Alert')}
                </span>
                <span className="ac-time">
                  {alert.created_at
                    ? new Date(alert.created_at).toLocaleTimeString()
                    : '--'}
                </span>
              </div>
            );
          })}
        </div>
      ) : (
        <div className="ac-empty">
          <div className="ac-empty-icon">🔔</div>
          No recent alerts
        </div>
      )}
    </div>
  );
});

export default AlertsCard;
